using System.Text;
using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Antiforgery;
static class Ui
{
    public static string E(string text)=>HtmlEncoder.Default.Encode(text);
    public static string Csrf(HttpContext c)=>"<input type='hidden' name='__RequestVerificationToken' value='"+E(c.RequestServices.GetRequiredService<IAntiforgery>().GetAndStoreTokens(c).RequestToken!)+"'>";
    public static string Form(HttpContext c,string action,string body)=>"<form method='post' action='"+action+"'>"+Csrf(c)+body+"</form>";
    public static IResult Error(HttpContext c,string title,string message,string back="/login",int status=400)=>Page(c,title,"<p class='notice'>"+E(message)+"</p><a class='button secondary' href='"+back+"'>Go back</a>",status,true);
    public static IResult Page(HttpContext c,string title,string body,int status=200,bool narrow=false,bool home=false)
    {
        var signed=c.User.Identity?.IsAuthenticated==true;
        var nav=signed?"<a href='/products'>Products</a><a href='/account'>Account</a>"+(c.User.IsInRole("admin")?"<a href='/admin'>Administration</a>":"")+Form(c,"/logout","<button class='nav-button'>Sign out</button>"):"<a href='/#products'>Products</a><a href='/docs'>Documentation</a><a href='/login'>Sign in</a><a class='nav-login' href='/register'>Register</a>";
        return Results.Content("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='description' content='Software Next Generation — UI components, reporting, remote desktop and video meetings for Linux, macOS and Windows.'><title>"+E(title)+" · Software Next Generation</title><link rel='icon' href='/brand.svg' type='image/svg+xml'><link rel='stylesheet' href='/site.css'><script src='/site.js' defer></script>"+(c.Request.Path.StartsWithSegments("/admin/licenses")||c.Request.Path.StartsWithSegments("/admin/customers")?"<link rel='stylesheet' href='/licensing.css'>":"")+(home?"<link rel='stylesheet' href='/home-showcase.css'><script src='/home-showcase.js' defer></script>":"")+"</head><body><header><a class='brand' href='/'><img src='/brand.svg' width='34' height='34' alt=''><span>nextgen<span class='brand-sub'>SOFTWARE</span></span></a><nav aria-label='Main navigation'>"+nav+"</nav></header><main class='"+(narrow?"narrow":home?"home":"workspace")+"'>"+(home?"":"<div class='page-heading'><span class='eyebrow'>SOFTWARE NEXT GENERATION</span><h1>"+E(title)+"</h1></div>")+body+"</main><footer><span>© "+DateTime.UtcNow.Year+" Software Next Generation</span><span>Tools for what comes next.</span><a href='/privacy'>Privacy</a></footer></body></html>","text/html",Encoding.UTF8,status);
    }
    public static IResult Home(HttpContext c)=>Page(c,"Build what comes next", $$"""
        <section class='hero'><div><div class='eyebrow'><span class='dot'></span> SOFTWARE NEXT GENERATION</div><h1>Good software.<br>Great possibilities<span class='accent'>.</span></h1><p class='hero-copy'>Thoughtful building blocks for ambitious applications. Build interfaces, design reports, access a remote desktop or bring your team together in a video meeting.</p><div class='actions'><a class='button' href='#products'>Explore our products <span>↗</span></a><a class='text-link' href='/register'>Create a customer account →</a></div><div class='hero-foot'><span>Built for developers</span><span>Designed for real work</span></div></div><a class='hero-product-scene' href='#live-previews' aria-label='Explore Components and Reports previews'><span class='hero-screen hero-screen-main'><span class='hero-screen-label'>NEXTGEN COMPONENTS</span><img src='/images/home/grid.webp' width='1200' height='800' alt='Actual NextgenComponents data grid preview' fetchpriority='high'></span><span class='hero-screen hero-screen-report'><span class='hero-screen-label'>NEXTGEN REPORT ENGINE</span><img src='/images/home/hero-report.png' width='800' height='1100' alt='Sales report generated by NextgenReportEngine'></span><span class='hero-scene-link'>Explore the live examples <span aria-hidden='true'>↗</span></span></a></section>
        <section class='intro-strip'><p>From the first component<br>to the final report.</p><span>Clear interfaces.</span><span>Flexible tools.</span><span>Practical documentation.</span></section>
        <section id='products' class='products-section'><div class='section-heading'><div><span class='eyebrow'>OUR PRODUCTS</span><h2>A focused toolkit.<br>A world of possibilities.</h2></div><p>Explore tools for building applications and working together across Linux, macOS and Windows.</p></div>{{ProductShowcase.Cards()}}</section>
        {{HomeShowcase.Render()}}<section class='values'><div><span>01 / BUILD</span><h3>Start with a solid foundation.</h3><p>Reusable components and practical examples help you move from idea to working application.</p></div><div><span>02 / LEARN</span><h3>Find your way, faster.</h3><p>Product guides, developer documentation and manuals live alongside your downloads.</p></div><div><span>03 / CREATE</span><h3>Your tools. Your workspace.</h3><p>Install on Linux, macOS or Windows and keep your development workflow close at hand.</p></div></section>
        <section class='cta'><div><span class='eyebrow'>YOUR NEXT STEP</span><h2>Ready when you are.</h2><p>Explore the documentation freely. Sign in for product downloads.</p></div><a class='button' href='/login'>Open your workspace ↗</a></section>
        """,home:true);
}
